BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats19-q01', '品質管理',
   '同じ工場で同じ機械を使って作っても、缶ジュース1本ごとの中身の量は、量ってみると350mlぴったりにはならず、349mlだったり352mlだったりと少しずつ違う。この「毎回起きるちょっとしたばらつき」を野放しにせず、原因を管理して品質を安定させようとする考え方を何と呼ぶ？',
   NULL::text,
   '["品質管理：ばらつきを管理して、製品やサービスの品質を安定させる考え方", "生産管理：生産の量や納期を管理して、計画通りに製品を仕上げる考え方", "検品：できあがった製品を1つずつ検査して、良品と不良品に分ける作業", "マーケティング：市場のニーズを細かく調べて、売り方や価格を考える活動"]',
   0, '[0]', 'single',
   '{"asked": "「ばらつき」を管理して品質を安定させる、という考え方の名前。", "point": "品質管理は、できた製品を選別することではなく、ばらつきの原因そのものを管理して、はじめから品質を安定させようとする考え方。", "kid": "同じ作り方をしても、機械でも人でも毎回まったく同じにはならない。この『ちょっとした違い』が大きくなりすぎないように見張って、いつも同じような品質を保とうとするのが品質管理。", "eg": "毎朝同じレシピで作るお弁当のごはんの量みたいなもの。よそうたびに少しずつ量が違うのは仕方ないけれど、『多すぎる日』『少なすぎる日』が出ないように、いつも同じくらいの量になるよう気をつけるのが品質管理の発想。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">同じ作り方でも、1本ごとに量が少しずつ違う</text><rect x=\"30\" y=\"34\" width=\"280\" height=\"52\" fill=\"#2a2f3f\" opacity=\"0.4\"/><text x=\"300\" y=\"46\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"end\">ふつうの範囲</text><line x1=\"30\" y1=\"108\" x2=\"310\" y2=\"108\" stroke=\"#2a2f3f\"/><rect x=\"48\" y=\"52\" width=\"20\" height=\"56\" fill=\"#3b82f6\"/><rect x=\"98\" y=\"58\" width=\"20\" height=\"50\" fill=\"#3b82f6\"/><rect x=\"148\" y=\"48\" width=\"20\" height=\"60\" fill=\"#3b82f6\"/><rect x=\"198\" y=\"62\" width=\"20\" height=\"46\" fill=\"#3b82f6\"/><rect x=\"248\" y=\"55\" width=\"20\" height=\"53\" fill=\"#3b82f6\"/><text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">このばらつきの原因を管理するのが品質管理</text></svg>", "terms": [["ばらつき", "同じように作っても、測定値が毎回少しずつ違うこと"], ["品質管理(QC)", "ばらつきの原因を管理して、品質を安定させる考え方。英語のQuality Controlの頭文字"]], "think": "なぜ『検査で不良品を弾く』だけではなく『ばらつきを管理する』という発想が必要かがカギ。できあがった製品を1つずつ検査して不良品を取り除くだけでは、不良品ができてしまうこと自体は防げない。材料や機械の調子、作業のやり方といった、ばらつきを生む原因の側を管理して安定させれば、そもそも不良品が生まれにくくなる。だから品質管理は、できた後の選別よりも、ばらつきの原因そのものに目を向ける。", "vs": "検品は『できあがった製品を1つずつ良品・不良品に分ける作業』であり、品質管理という考え方の一部の手段にすぎない。品質管理はもっと広く、ばらつきの原因そのものを管理する考え方全体を指す。", "why_asked": "この先に出てくる管理図や工程能力指数は、すべて『ばらつきを管理する』という品質管理の考え方を、具体的な図や数字で実行するための道具。まず品質管理そのものが何を目指しているかを押さえておかないと、道具の意味が分からなくなる。", "usecase": "工場の生産ラインだけでなく、コールセンターの応答時間、飲食店の味の再現性など、『毎回同じような結果を安定して出したい』場面すべてに関わる考え方。", "opt": ["正解。品質管理は、製品やサービスに生じるばらつきの原因を管理して、品質を安定させようとする考え方。", "生産管理は生産の量や納期を管理する考え方。ばらつきそのものを管理して品質を安定させる品質管理とは目的が異なる。", "検品はできあがった製品を1つずつ検査して選別する作業。ばらつきの原因を管理する品質管理より狭い、手段の1つにあたる。", "マーケティングは市場のニーズや売り方を考える活動。製品のばらつきを管理する品質管理とは扱う対象が違う。"]}'),

  ('stats19-q02', '品質管理',
   '工場で毎時間、製品の重さを1個ずつ測って記録していく。この記録を時間の順に点でプロットし、正常なばらつきの範囲(のちに出てくる管理限界線)を超えていないか一目で確認できるようにした図を何と呼ぶ？',
   NULL::text,
   '["管理図：データを時間順にプロットし、範囲を超えていないか見る図", "散布図：2つの変量の値を点で表し、両者の関係の強さを見る図", "ヒストグラム：データを値の範囲ごとに区切り、度数を棒の高さで表した図", "箱ひげ図：データの四分位数や外れ値を1つの図にまとめて表した図"]',
   0, '[0]', 'single',
   '{"asked": "時間順にデータをプロットして、正常なばらつきを超えていないか見る図の名前。", "point": "管理図は、データを時間の順に並べてプロットし、いつもの範囲からはみ出していないかを目で見て確認するための図。", "kid": "毎時間はかった重さを、横軸を時間にして順番に点で打っていく図。点がいつもの範囲の中に収まっているうちは『いつも通り』、範囲からはみ出したら『何かおかしいかも』とすぐ気づける。", "eg": "体温を毎朝記録するグラフのようなもの。いつもの体温の範囲に点が収まっていれば安心、急に高い場所に点が飛び出したら『何かおかしい』とすぐ分かる。管理図もそれと同じしくみを工場の測定値に使う。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">時間の順に点を打ち、範囲からはみ出していないか見る</text><line x1=\"30\" y1=\"40\" x2=\"310\" y2=\"40\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/><line x1=\"30\" y1=\"95\" x2=\"310\" y2=\"95\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/><text x=\"313\" y=\"43\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"start\">上限</text><text x=\"313\" y=\"98\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"start\">下限</text><polyline points=\"50,60 90,68 130,55 170,72 210,64 250,58 290,66\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.8\"/><circle cx=\"50\" cy=\"60\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"90\" cy=\"68\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"130\" cy=\"55\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"170\" cy=\"72\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"210\" cy=\"64\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"250\" cy=\"58\" r=\"2.5\" fill=\"#e8eaf0\"/><circle cx=\"290\" cy=\"66\" r=\"2.5\" fill=\"#e8eaf0\"/><text x=\"170\" y=\"118\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">横軸=時間の順番　点が内側なら正常</text></svg>", "terms": [["管理図", "データを時間順にプロットし、正常なばらつきの範囲を超えていないか見る図"], ["時系列", "時間の順に並んだデータ。管理図は時系列のデータを扱う"]], "think": "なぜ『時間順』に並べることが大事かがカギ。同じ数のデータでも、ヒストグラムのようにただ値の分布だけを見ると、いつからばらつきが大きくなったのかが分からない。時間順に並べてプロットすることで、『先週までは範囲内だったのに、今週から急に外側に出るようになった』のように、いつ異常が始まったかを追いかけられる。", "vs": "散布図は2つの変量(たとえば身長と体重)の関係を見る図で、横軸は時間ではない。ヒストグラムや箱ひげ図はデータ全体の分布の形を見る図で、こちらも時間の順番は考えない。管理図だけが『時間の順番』を横軸に使う。", "why_asked": "この先の中心線・管理限界線・偶然原因と異常原因の見分け方は、すべて『時間順にプロットする』という管理図の土台の上に成り立つ。まず管理図が何を横軸・縦軸にした図なのかを押さえておく必要がある。", "usecase": "工場の生産ラインの寸法や重さの監視、コールセンターの応答時間の推移の監視など、『時間とともに数値がどう動いているか』を継続的に見守りたい場面で使う。", "opt": ["正解。管理図はデータを時間の順にプロットし、正常なばらつきの範囲を超えていないかを見る図。", "散布図は2つの変量の関係を見る図で、横軸は時間ではない。時間順の推移を見る管理図とは目的が違う。", "ヒストグラムは値の範囲ごとの度数を棒で表す図で、時間の順番は表さない。いつ異常が起きたかは分からない。", "箱ひげ図はデータ全体の分布の形をまとめる図で、こちらも時間の順番は表さない。"]}'),

  ('stats19-q03', '品質管理',
   'ある工場の管理図には、中心線60g・上方管理限界(UCL)66g・下方管理限界(LCL)54gという3本の横線が引かれている。これらの線はそれぞれ何を表しているか？',
   NULL::text,
   '["中心線は工程の平均(60g)。UCLとLCLは偶然のばらつきの許容範囲(66gと54g)", "中心線は製品の規格の中央値。UCLとLCLは出荷してよい製品の重さの上限と下限を表す", "中心線はこれまでの最頻値。UCLとLCLはこれまでに記録された重さの最大値と最小値を表す", "中心線は目標とする最小値。UCLとLCLは検査で不合格になった個数の上限と下限を表す"]',
   0, '[0]', 'single',
   '{"asked": "管理図の中心線・上方管理限界・下方管理限界という3本の線が、それぞれ何を表しているか。", "point": "中心線は工程のふだんの平均。UCLとLCLは、その平均から見て『偶然のばらつきとして許される範囲』の上と下の境界。", "kid": "中心線は、いつも通り作ったときの真ん中あたりの値。UCL(上方管理限界)とLCL(下方管理限界)は、『このくらいまでの上下のブレなら、いつも通りのばらつきの範囲内』という境界線。", "eg": "毎朝はかる体重にたとえると、中心線はふだんの体重(たとえば60kg)。UCLとLCLは『前日と比べて数kgくらいまでなら、いつも通りの範囲』という上下の境界線のようなもの。境界を超えたら『何か変化があったかも』と気づく。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">3本の線：中心線・上方管理限界(UCL)・下方管理限界(LCL)</text><line x1=\"30\" y1=\"34\" x2=\"264\" y2=\"34\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/><line x1=\"30\" y1=\"68\" x2=\"264\" y2=\"68\" stroke=\"#e8eaf0\" stroke-width=\"1.3\"/><line x1=\"30\" y1=\"102\" x2=\"264\" y2=\"102\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/><text x=\"270\" y=\"37\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"start\">UCL 66g</text><text x=\"270\" y=\"71\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"start\">中心線 60g</text><text x=\"270\" y=\"105\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"start\">LCL 54g</text><circle cx=\"50\" cy=\"60\" r=\"2.3\" fill=\"#3b82f6\"/><circle cx=\"80\" cy=\"78\" r=\"2.3\" fill=\"#3b82f6\"/><circle cx=\"110\" cy=\"52\" r=\"2.3\" fill=\"#3b82f6\"/><circle cx=\"140\" cy=\"86\" r=\"2.3\" fill=\"#3b82f6\"/><circle cx=\"170\" cy=\"64\" r=\"2.3\" fill=\"#3b82f6\"/><circle cx=\"200\" cy=\"72\" r=\"2.3\" fill=\"#3b82f6\"/><circle cx=\"230\" cy=\"58\" r=\"2.3\" fill=\"#3b82f6\"/><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">点はふつう、中心線の周りをUCL・LCLの内側で揺れる</text></svg>", "terms": [["中心線", "工程のふだんの平均を表す線"], ["上方管理限界(UCL)", "偶然のばらつきとして許される範囲の上の境界線"], ["下方管理限界(LCL)", "偶然のばらつきとして許される範囲の下の境界線"]], "think": "なぜ中心線1本だけでなく、上下2本の境界線も引くのかがカギ。中心線だけでは『ふだんの真ん中』は分かっても、『どこまでのズレならふつうか』が分からない。そこでUCLとLCLという2本の境界線を、中心線から離れた位置に引くことで、『この範囲の中で点が揺れている限りは、いつも通りの偶然のばらつき』と判断できるようにする。逆にこの範囲を点が超えたら、いつも通りでは説明できない何かが起きたサインになる。", "vs": "UCL・LCLは『製品として出荷してよい範囲(規格)』とは別物。規格は『お客様に約束した範囲』、UCL・LCLは『工程がいつも通り動いているときの、偶然のばらつきの範囲』。工程が安定していても、規格の範囲とUCL・LCLの範囲は一致するとは限らない。", "why_asked": "この先に出てくる『偶然原因と異常原因の見分け方』は、点がこのUCL・LCLの内側か外側かで判断する。まず3本の線がそれぞれ何を意味するかを取り違えると、その先の判断がすべてずれてしまう。", "usecase": "実際の管理図を読むとき、中心線からどれだけ離れているか、UCL・LCLの内側に収まっているかを見て、工程が『いつも通り』かどうかを判断する。", "opt": ["正解。中心線は工程の平均(60g)。UCLとLCLは、平均から見て偶然のばらつきとして許される範囲の上下の境界(66gと54g)。", "UCL・LCLは『出荷してよい製品の範囲(規格)』ではなく、『工程がいつも通り動いているときの、偶然のばらつきの範囲』を表す。規格とは別物。", "中心線は『これまでの平均』であり、最頻値ではない。UCL・LCLも記録の最大値・最小値ではなく、あらかじめ計算で定める境界線。", "中心線は目標の最小値ではなく工程の平均。UCL・LCLも不合格の個数ではなく、重さそのもののばらつきの境界線。"]}'),

  ('stats19-q04', '品質管理',
   '管理図の点の多くはUCL・LCLの内側で、上下に細かく揺れながら散らばっている。しかし時々、機械の故障や材料のロット変更などをきっかけに、点がUCL・LCLの外側に飛び出すことがある。この「いつも通りの、原因を突き止めても仕方のない小さなばらつき」と「機械の故障など、何かがおかしくなって生じる大きなばらつき」を、それぞれ何と呼ぶか？',
   NULL::text,
   '["前者を偶然原因によるばらつき、後者を異常原因によるばらつきと呼ぶ", "前者を異常原因によるばらつき、後者を偶然原因によるばらつきと呼ぶ", "前者を系統誤差、後者を測定誤差と呼ぶ", "前者を標本誤差、後者を非標本誤差と呼ぶ"]',
   0, '[0]', 'single',
   '{"asked": "『いつも通りの小さなばらつき』と『何かがおかしくなって生じる大きなばらつき』をそれぞれ何と呼ぶか。", "point": "いつも通りの、突き止めても仕方のない小さなばらつきは偶然原因。機械の故障など、何かがおかしくなって生じるばらつきは異常原因。", "kid": "偶然原因は、どんなに気をつけても消せない『いつも通りのちょっとしたブレ』。異常原因は、機械が壊れたり材料が変わったりと、何か特定のきっかけがあって起きる『いつもとは違う、原因を探せば見つかるブレ』。", "eg": "毎朝同じ時間に起きても、目覚める時刻が1〜2分前後するのは偶然原因のようなもの(気にしても仕方がない)。ところがある日、目覚まし時計が壊れて2時間も寝坊したら、それは目覚まし時計の故障という異常原因がある。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">ふだんの小さな揺れと、たまに起きる大きな飛び出し</text><rect x=\"30\" y=\"48\" width=\"280\" height=\"50\" fill=\"#2a2f3f\" opacity=\"0.35\"/><circle cx=\"55\" cy=\"66\" r=\"2.3\" fill=\"#3b82f6\"/><circle cx=\"85\" cy=\"78\" r=\"2.3\" fill=\"#3b82f6\"/><circle cx=\"115\" cy=\"70\" r=\"2.3\" fill=\"#3b82f6\"/><circle cx=\"150\" cy=\"84\" r=\"2.3\" fill=\"#3b82f6\"/><circle cx=\"185\" cy=\"63\" r=\"2.3\" fill=\"#3b82f6\"/><circle cx=\"220\" cy=\"76\" r=\"2.3\" fill=\"#3b82f6\"/><circle cx=\"250\" cy=\"68\" r=\"2.3\" fill=\"#3b82f6\"/><text x=\"90\" y=\"110\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">偶然原因（いつも通りの揺れ）</text><circle cx=\"280\" cy=\"24\" r=\"3\" fill=\"#c47070\"/><text x=\"280\" y=\"40\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">異常原因</text><text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">外側の点＝異常原因のサイン</text></svg>", "terms": [["偶然原因", "いつも通りに生じる、突き止めても仕方のない小さなばらつきの原因"], ["異常原因", "機械の故障や材料の変化など、何かがおかしくなって生じるばらつきの原因"]], "think": "なぜこの2つを区別する必要があるのかがカギ。偶然原因によるいつも通りの小さなブレに対して、いちいち『なぜだ』と原因調査をして機械を止めていたら、時間と労力の無駄になる。逆に、異常原因による大きなブレを『いつも通りのブレの一種』だと見過ごしてしまうと、不良品が量産されるまで気づけない。管理図でUCL・LCLの内側か外側かを見るのは、この2つを区別して、対応が必要なブレだけに絞り込むため。", "vs": "『ばらつきがある』という点だけを見ると偶然原因も異常原因も同じに見えるが、対応のしかたがまったく違う。偶然原因には手を出さず工程をそのまま見守り、異常原因には原因を探して取り除く対応をとる。", "why_asked": "管理図を『点が線の外に出たら異常』というルールだけで機械的に覚えると、なぜそのルールが成り立つのかが分からなくなる。偶然原因と異常原因という2種類のばらつきがあるという前提があってはじめて、UCL・LCLという境界線の意味が理解できる。", "usecase": "工程が『いつも通り安定して動いているか』を判断するとき、この2つの原因の違いを踏まえて、対応すべき異常だけに絞って手を打つ。", "opt": ["正解。いつも通りの小さなばらつきの原因を偶然原因、機械の故障など何かがおかしくなって生じるばらつきの原因を異常原因と呼ぶ。", "偶然原因と異常原因の対応が入れ替わっている。いつも通りの小さなばらつきは偶然原因、何かがおかしくなって生じるばらつきは異常原因。", "系統誤差・測定誤差は測定のしかたにかたよりや誤差が生じる話であり、工程のばらつきの原因を指す偶然原因・異常原因とは別の言葉。", "標本誤差・非標本誤差は標本調査で使う言葉であり、工程のばらつきの原因を指す偶然原因・異常原因とは別の言葉。"]}'),

  ('stats19-q05', '品質管理',
   'すべての点がUCL・LCLの内側にあるにもかかわらず、「何かおかしいかもしれない」と判断できるパターンがある。次のうち、それにあたるのはどれか？',
   NULL::text,
   '["点が7回以上連続して、中心線の同じ側にばかり並んでいる", "点が中心線をはさんで上下にランダムに散らばっている", "点がUCL・LCLのちょうど真ん中あたりに集中している", "記録した点の数が、ちょうど30点に達している"]',
   0, '[0]', 'single',
   '{"asked": "点がすべてUCL・LCLの内側にあっても『異常かもしれない』と判断できるパターン。", "point": "点が管理限界線の外に出ていなくても、7回以上連続して中心線の同じ側に並んでいたら、それも異常のサイン。", "kid": "管理図の異常サインは『線の外に飛び出す』だけではない。線の内側にずっと収まっていても、点が何回も続けて中心線の片側だけに偏っていたら、それは偶然にしては起きすぎている、何かのクセがあるサインとみなす。", "eg": "コインを投げて表が出るか裏が出るかのようなもの。表と裏はだいたい半々で出るはずなのに、7回連続で表ばかり出たら、『このコインは表が出やすいように偏っているのでは』と疑うのと同じ発想。", "viz": "<svg viewBox=\"0 0 340 136\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">線の内側でも、同じ側に7回連続で並ぶのは異常サイン</text><line x1=\"30\" y1=\"30\" x2=\"310\" y2=\"30\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/><line x1=\"30\" y1=\"64\" x2=\"310\" y2=\"64\" stroke=\"#e8eaf0\" stroke-width=\"1.1\"/><line x1=\"30\" y1=\"98\" x2=\"310\" y2=\"98\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/><polyline points=\"45,50 75,46 105,52 135,42 165,48 195,44 225,50\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.6\"/><circle cx=\"45\" cy=\"50\" r=\"2.6\" fill=\"#c9a04a\"/><circle cx=\"75\" cy=\"46\" r=\"2.6\" fill=\"#c9a04a\"/><circle cx=\"105\" cy=\"52\" r=\"2.6\" fill=\"#c9a04a\"/><circle cx=\"135\" cy=\"42\" r=\"2.6\" fill=\"#c9a04a\"/><circle cx=\"165\" cy=\"48\" r=\"2.6\" fill=\"#c9a04a\"/><circle cx=\"195\" cy=\"44\" r=\"2.6\" fill=\"#c9a04a\"/><circle cx=\"225\" cy=\"50\" r=\"2.6\" fill=\"#c9a04a\"/><text x=\"135\" y=\"30\" fill=\"#c9a04a\" font-size=\"8\" text-anchor=\"middle\" dy=\"-4\">7回連続で中心線より上</text><text x=\"170\" y=\"118\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">線の外に出ていなくても「偏り」は異常のサイン</text></svg>", "terms": [["ラン(連)", "点が中心線の同じ側に何回も連続して並ぶこと。管理限界線の外に出ていなくても異常のサインとされる"], ["管理図の異常判定ルール", "線の外に出ることだけでなく、連続した偏りなど複数のパターンで異常を判定するルールのまとめ"]], "think": "なぜ線の外に出ていないのに異常だと判断できるのかがカギ。もし工程が本当に偶然原因だけでいつも通り動いているなら、点は中心線の上と下にだいたい半々くらいの確率でランダムに散らばるはずで、片側に7回も連続して並ぶことは滅多に起きない。にもかかわらず7回以上同じ側に連続したなら、『たまたま』では説明しづらく、工程の平均そのものがどちらかに少しずれ始めた、といった異常のサインだと考える。", "vs": "『線の外に出る』は分かりやすい異常サインだが、それだけを見ていると『線の内側だけど明らかに片側に偏っている』という異常を見逃してしまう。管理図を読むときは、線の外側だけでなく点の並び方のクセにも注目する。", "why_asked": "管理図は『外に出たら異常』という単純なルールだけで運用すると、偏りが小さいうちの異常に気づけない。連続した偏りのようなパターンも異常のサインになるという直感を持っておくことが、実務での早期発見につながる。", "usecase": "生産ラインの担当者が管理図を毎日見るとき、点が線の外に出ていなくても、同じ側への偏りが続いていないかをあわせてチェックする。", "opt": ["正解。点が7回以上連続して中心線の同じ側に並ぶのは、偶然だけでは起きにくいパターンで、異常のサインとされる。", "点が中心線をはさんで上下にランダムに散らばっているのは、むしろ偶然原因だけで動いている『いつも通り』の状態を示す。", "点が中心線の近くに集中しているのは、ばらつきが小さく安定していることを示すもので、異常のサインではない。", "点の数が30点に達したこと自体は、データを一定数集めたというだけの話で、異常のサインとは関係がない。"]}'),

  ('stats19-q06', '品質管理',
   'ねじの直径の規格は9.4mm〜10.6mm(規格の上限と下限の幅は1.2mm)。実際に生産したねじの直径のばらつき(標準偏差)は0.1mmだった。工程能力指数 Cp = 規格の幅 ÷ (6×標準偏差) で求めると、Cpはいくつになる？',
   NULL::text,
   '["2.0（規格の幅1.2mmを、6×標準偏差0.6mmで割った値）", "1.2（規格の幅の数字を、そのままCpの値としてしまっている）", "12（6倍する部分を忘れ、規格の幅1.2mmを標準偏差0.1mmだけで割ってしまっている）", "0.6（6×標準偏差の計算結果を、そのままCpの値としてしまっている）"]',
   0, '[0]', 'single',
   '{"asked": "規格の幅と標準偏差から、工程能力指数Cpを計算する。", "point": "Cp＝規格の幅÷(6×標準偏差)。数字が大きいほど、ばらつきに対して規格の幅に余裕があることを表す。", "kid": "Cpは、『規格として許されている幅』が、『実際のばらつきの広さ』の何倍あるかを表す数字。数字が大きいほど、規格の幅に対してばらつきが小さく、余裕があるということ。", "eg": "駐車スペースの幅(規格の幅)と、車の実際の横幅のばらつき(標準偏差)を比べるようなもの。駐車スペースが車の幅よりずっと広ければ余裕を持って止められるし(Cpが大きい)、駐車スペースが車の幅とほとんど同じなら、少しでもずれるとはみ出してしまう(Cpが小さい)。", "viz": "<svg viewBox=\"0 0 340 136\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">規格の幅と、ばらつきの幅(6×標準偏差)を比べる</text><text x=\"170\" y=\"34\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">規格の幅 1.2mm</text><rect x=\"40\" y=\"42\" width=\"260\" height=\"24\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.2\"/><rect x=\"105\" y=\"42\" width=\"130\" height=\"24\" fill=\"#3b82f6\"/><text x=\"170\" y=\"58\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">6×標準偏差 0.6mm</text><line x1=\"105\" y1=\"72\" x2=\"105\" y2=\"82\" stroke=\"#8892a4\" stroke-width=\"1\"/><line x1=\"235\" y1=\"72\" x2=\"235\" y2=\"82\" stroke=\"#8892a4\" stroke-width=\"1\"/><line x1=\"40\" y1=\"88\" x2=\"300\" y2=\"88\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"170\" y=\"100\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">外側と内側のすき間が「余裕」</text><text x=\"170\" y=\"122\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"700\">Cp = 1.2 ÷ 0.6 = 2.0</text></svg>", "terms": [["工程能力指数(Cp)", "製品のばらつきが、規格の幅に対してどれくらい余裕があるかを表す指標"], ["規格の幅", "規格の上限と下限の差。ここでは10.6mm−9.4mm=1.2mm"]], "calc": "規格の上限(USL)   10.6mm\n規格の下限(LSL)    9.4mm\n規格の幅  10.6−9.4 = 1.2mm\n\n標準偏差 σ = 0.1mm\n6×σ = 6×0.1 = 0.6mm\n\nCp = 規格の幅÷6σ = 1.2÷0.6 = 2.0", "think": "なぜ標準偏差を6倍してから比べるのかがカギ。以前学んだ『68-95ルール』のように、正規分布に近いばらつきなら、平均から標準偏差の3倍離れたところまでの範囲に、ほぼ全部のデータが収まる。上側に3σ、下側に3σで合わせて6σが、ばらつきが実際に広がる幅のめやすになる。規格の幅をこの6σで割ることで、『規格の幅は、実際のばらつきの広がりの何倍あるか』を1つの数字で表せる。だからCpの式は規格の幅を6×標準偏差で割る。", "vs": "規格の幅の数字(1.2mm)や6×標準偏差の数字(0.6mm)は、それぞれ計算の途中の値であって、Cpの答えそのものではない。Cpは『規格の幅÷6×標準偏差』という割り算をした後の値であることを忘れない。", "why_asked": "Cpは品質管理の実務で工程の余裕を1つの数字で判断するための、代表的な指標。計算の仕組みを理解していないと、次に出てくる『Cpの値をどう読むか』(1.33以上・1.0未満の目安)も丸暗記になってしまう。", "usecase": "新しい製品の規格を決めるときや、工程を見直すときに、Cpを計算して『この工程には十分な余裕があるか』を数値で確認する。", "opt": ["正解。規格の幅1.2mmを6×標準偏差0.6mmで割ると、Cp=1.2÷0.6=2.0になる。", "1.2mmは規格の幅そのものの値で、まだ標準偏差で割る前の途中の数字。これをそのままCpの値にはできない。", "12は規格の幅1.2mmを標準偏差0.1mmだけで割った値で、『6倍する』計算を忘れている。正しくは6×標準偏差0.6mmで割る。", "0.6mmは6×標準偏差の計算結果であって、規格の幅と比べる前の途中の数字。これ自体がCpの値ではない。"]}'),

  ('stats19-q07', '品質管理',
   '別の工程で同じようにCpを計算したところ、0.8だった。これは1.33や1.0といっためやすと比べて、どちらの状態を示しているか？',
   NULL::text,
   '["Cpが1.0を下回っており、規格の幅に対してばらつきが大きすぎるため、規格外れが増えやすい状態", "Cpが1.33以上あるので、ばらつきに十分な余裕があり、規格から外れる製品はほとんど心配ない状態", "Cpは値が大きいほど工程に問題があることを意味するため、0.8はむしろ余裕のある良好な状態", "Cpが1.0にちょうど近い値なので、規格の幅とばらつきの幅が釣り合った、理想的な状態"]',
   0, '[0]', 'single',
   '{"asked": "Cp=0.8という値を、1.33や1.0というめやすと照らし合わせてどう読むか。", "point": "Cpは1.33以上あれば十分、1.0を下回ると規格から外れる製品が増えやすい、というのがよく使われるめやす。", "kid": "Cpの数字が大きいほど、規格の幅に対してばらつきが小さく余裕がある。だいたい1.33以上あれば十分な余裕があるとされ、1.0を下回ると、ばらつきが規格の幅に対して大きすぎて、規格から外れる製品が増えやすくなる。", "eg": "駐車スペースの幅と車の幅の余裕にたとえると、Cpが1.33以上は『多少ハンドル操作がぶれても余裕で収まる広さ』、Cpが1.0を下回るのは『少しでもずれると車体がラインからはみ出してしまう狭さ』にあたる。", "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">Cpのめやす：1.33以上は十分、1.0未満は要注意</text><rect x=\"30\" y=\"52\" width=\"140\" height=\"16\" fill=\"#c47070\" opacity=\"0.55\"/><rect x=\"170\" y=\"52\" width=\"46.2\" height=\"16\" fill=\"#c9a04a\" opacity=\"0.55\"/><rect x=\"216.2\" y=\"52\" width=\"93.8\" height=\"16\" fill=\"#6ab08d\" opacity=\"0.55\"/><line x1=\"170\" y1=\"46\" x2=\"170\" y2=\"70\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"170\" y=\"44\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">1.0</text><line x1=\"216.2\" y1=\"46\" x2=\"216.2\" y2=\"70\" stroke=\"#8892a4\" stroke-width=\"1\"/><text x=\"216.2\" y=\"44\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">1.33</text><line x1=\"142\" y1=\"28\" x2=\"142\" y2=\"50\" stroke=\"#e8eaf0\" stroke-width=\"1.3\"/><polygon points=\"142,50 138,42 146,42\" fill=\"#e8eaf0\"/><text x=\"142\" y=\"24\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">Cp=0.8</text><text x=\"170\" y=\"112\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0.8は1.0未満 → 規格外れが増えやすい</text></svg>", "terms": [["Cpのめやす", "1.33以上なら十分、1.0を下回ると規格外れが増えやすい、というよく使われる目安"], ["規格外れ", "製品の値が規格の上限・下限の外側に出てしまうこと"]], "think": "なぜ1.0という数字が境目になるのかがカギ。Cp=1.0は、規格の幅とちょうど6×標準偏差が等しい状態を意味する。つまり、ばらつきの広がりが規格の幅ぎりぎりまで達しているということなので、平均が少しでもずれたり、ばらつきが少し大きくなったりするだけで、すぐに規格の外側にはみ出す製品が出てしまう。Cpが1.0を下回るということは、ばらつきの広がりが規格の幅を上回っている状態で、規格から外れる製品はさらに増えやすくなる。だから1.0を境目に『余裕がない』と判断する。1.33はそこにさらに余裕を持たせた、より安全なめやす。", "vs": "『Cpの数字が大きいほど良い』という向きを取り違えないこと。Cpは規格の幅に対する余裕の大きさを表すので、数字が大きいほど工程は安定していて余裕がある。0.8は1.0を下回っているので、余裕が足りない側の状態。", "why_asked": "Cpを計算できても、その数字が良いのか悪いのかを読めなければ実務で使えない。1.33・1.0というめやすを知っておくことで、計算した数値から『対策が必要かどうか』を判断できるようになる。", "usecase": "工程を見直したあとにCpを再計算し、1.33以上に達したかどうかで、対策が十分だったかを判断する場面で使う。", "opt": ["正解。Cp=0.8は1.0を下回っており、ばらつきが規格の幅に対して大きすぎるため、規格から外れる製品が増えやすい状態を示す。", "1.33以上というのは十分な余裕があるめやすだが、0.8は1.0すら下回っており、この状態にはあてはまらない。", "Cpは数字が大きいほど余裕があり良好な状態を示す指標であり、数字が大きいほど問題があるというのは向きが逆。", "Cp=1.0はちょうど規格の幅とばらつきの広がりが等しく、余裕がぎりぎりの状態。0.8はその1.0すら下回っており、理想的とは言えない。"]}'),

  ('stats19-q08', '品質管理',
   '管理図で「点が管理限界線の外に出たら、工程に異常が起きたと判断する」という考え方は、以前学んだ仮説検定の発想とどう似ているか？',
   NULL::text,
   '["「工程は正常」を帰無仮説とし、めったに起きない値が出たら「異常あり」と判断する点が仮説検定と同じ", "管理図はデータを時間順に並べるだけの図であり、仮説を立てて検証する仮説検定とはまったく関係がない", "管理図では点をプロットするたびに必ずp値を計算しており、それ自体が仮説検定と同じ意味を持つ", "管理図の管理限界線は、仮説検定でいう効果量にあたるものであり、有意水準とは無関係である"]',
   0, '[0]', 'single',
   '{"asked": "管理図の『線の外に出たら異常』という判断が、仮説検定の考え方とどう似ているか。", "point": "『工程は正常』を帰無仮説とみなし、偶然ではめったに起きない値が出たら『異常あり』と判断する。この骨組みが仮説検定と同じ。", "kid": "仮説検定は『差はない』という仮説を置いておいて、めったに起きないはずの結果が出たら『差はないとは考えにくい』と判断するやり方。管理図も同じように、『工程はいつも通り(偶然原因の範囲内)』という前提を置いておいて、めったに起きないはずの値(管理限界線の外)が出たら『いつも通りとは考えにくい=異常』と判断する。", "eg": "『このサイコロはいかさまではない』という前提のもとで、1の目ばかり10回連続で出たら『さすがにこの前提はおかしいのでは』と疑うのと同じ発想。管理図も『工程は正常』という前提のもとで、めったに起きない値が出たら前提を疑う。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じ発想の骨組み</text><text x=\"95\" y=\"30\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">仮説検定</text><text x=\"245\" y=\"30\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">管理図</text><line x1=\"170\" y1=\"22\" x2=\"170\" y2=\"128\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><rect x=\"35\" y=\"38\" width=\"120\" height=\"18\" fill=\"#2a2f3f\"/><text x=\"95\" y=\"50\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">前提：差はない</text><rect x=\"185\" y=\"38\" width=\"120\" height=\"18\" fill=\"#2a2f3f\"/><text x=\"245\" y=\"50\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">前提：工程は正常</text><line x1=\"95\" y1=\"58\" x2=\"95\" y2=\"68\" stroke=\"#8892a4\"/><polygon points=\"95,71 91,64 99,64\" fill=\"#8892a4\"/><line x1=\"245\" y1=\"58\" x2=\"245\" y2=\"68\" stroke=\"#8892a4\"/><polygon points=\"245,71 241,64 249,64\" fill=\"#8892a4\"/><rect x=\"35\" y=\"72\" width=\"120\" height=\"18\" fill=\"#2a2f3f\"/><text x=\"95\" y=\"84\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">めったに起きない値</text><rect x=\"185\" y=\"72\" width=\"120\" height=\"18\" fill=\"#2a2f3f\"/><text x=\"245\" y=\"84\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">線の外に出る</text><line x1=\"95\" y1=\"92\" x2=\"95\" y2=\"102\" stroke=\"#8892a4\"/><polygon points=\"95,105 91,98 99,98\" fill=\"#8892a4\"/><line x1=\"245\" y1=\"92\" x2=\"245\" y2=\"102\" stroke=\"#8892a4\"/><polygon points=\"245,105 241,98 249,98\" fill=\"#8892a4\"/><rect x=\"35\" y=\"106\" width=\"120\" height=\"18\" fill=\"#3b82f6\"/><text x=\"95\" y=\"118\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"600\">棄却＝差あり</text><rect x=\"185\" y=\"106\" width=\"120\" height=\"18\" fill=\"#3b82f6\"/><text x=\"245\" y=\"118\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"600\">異常と判断</text><text x=\"170\" y=\"136\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">＝どちらも「前提を疑うタイミング」の決め方が同じ</text></svg>", "terms": [["帰無仮説", "否定されることを想定して立てる仮説。ここでは『工程は偶然原因の範囲内で正常』にあたる"], ["有意水準", "帰無仮説を疑い始める『めったに起きない』の基準。管理図ではUCL・LCLがこれに近い役割を果たす"]], "think": "なぜ2つの考え方が似ているのかがカギ。どちらも『いつも通り・差はない』という前提を最初に置き、その前提のもとでは滅多に起きないはずの結果が実際に観測されたときに、『その前提は成り立っていないのでは』と判断を切り替える、という同じ骨組みを持っている。仮説検定ではp値や有意水準を使ってこの『滅多に起きない』を判断し、管理図では管理限界線(UCL・LCL)の内側か外側かで同じ役割を果たしている。道具の形は違っても、『前提を疑うタイミングを、確率的にめったに起きないことが起きたかどうかで決める』という考え方は共通している。", "vs": "『管理図はただのグラフで、統計的な判断とは関係ない』と思ってしまいやすいが、UCL・LCLという境界線自体が、あらかじめ『偶然ならこの範囲に収まるはず』という確率的な計算に基づいて引かれている。単なる見た目のグラフではなく、統計的な判断の道具である点が仮説検定と共通する。", "why_asked": "品質管理と仮説検定は別々の単元で学ぶことが多く、つながりに気づきにくい。両方とも『前提を置き、めったに起きないことが起きたら前提を疑う』という同じ発想の上に成り立っていると分かると、それぞれの理解が深まる。", "usecase": "新しい工程やシステムの監視の仕組みを設計するとき、『何が起きたら異常と判断するか』という基準を、仮説検定と同じ発想(めったに起きないことが基準)で作る場面で活きる。", "opt": ["正解。『工程は正常』を帰無仮説とみなし、偶然ではめったに起きない値が出たら『異常あり』と判断する骨組みが、仮説検定と同じ。", "管理限界線(UCL・LCL)自体が、偶然ならどの範囲に収まるはずかという確率的な計算に基づいており、仮説検定の考え方と関係がないとは言えない。", "管理図は点をプロットするたびに必ずp値を計算しているわけではない。あらかじめ計算しておいたUCL・LCLと見比べる、という仕組み。", "管理限界線は『めったに起きないと判断する基準』という点で有意水準に近い役割を果たしており、効果量とは異なる。"]}'),

  ('stats19-q09', '品質管理',
   '段ボール1000個の製品ロットを検査するとき、「1000個全部を検査する」方法と、「そこから100個だけ無作為に抜き取って検査する」方法がある。これらは、既に学んだ「全数調査」「標本調査」のどちらにそれぞれ対応するか？',
   NULL::text,
   '["「1000個全部」は全数調査にあたる全数検査、「100個だけ抜き取る」は標本調査にあたる抜取検査", "「1000個全部」は標本調査にあたる全数検査、「100個だけ抜き取る」は全数調査にあたる抜取検査", "製品を検査する場合、対象がどちらでも必ず標本調査に分類される", "製品を検査する場合、対象がどちらでも必ず全数調査に分類される"]',
   0, '[0]', 'single',
   '{"asked": "全数検査・抜取検査が、既習の全数調査・標本調査のどちらにそれぞれ対応するか。", "point": "対象を全部調べる全数検査は全数調査、一部を無作為に抜き取って調べる抜取検査は標本調査にあたる。", "kid": "全数検査は、母集団(1000個全部)を1つ残らず調べる方法なので全数調査そのもの。抜取検査は、母集団の一部(100個)だけを無作為に選んで調べる方法なので標本調査そのもの。品質管理の場面での呼び方が違うだけで、考え方は既に学んだ全数調査・標本調査と同じ。", "eg": "クラス全員の身長を1人残らず測るのが全数調査、クラスから10人だけくじ引きで選んで測るのが標本調査。これを製品検査に当てはめると、1000個全部を検査するのが全数検査、そこから100個だけ抜き取って検査するのが抜取検査になる。", "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">全数検査＝1000個全部を検査（全数調査）</text><rect x=\"30.0\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"41.4\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"52.8\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"64.2\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"75.6\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"87.0\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"98.4\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"109.8\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"121.2\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"132.6\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"144.0\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"155.4\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"166.8\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"178.2\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"189.6\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"201.0\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"212.4\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"223.8\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"235.2\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"246.6\" y=\"42.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"30.0\" y=\"52.4\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"41.4\" y=\"52.4\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"52.8\" y=\"52.4\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"64.2\" y=\"52.4\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"75.6\" y=\"52.4\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"87.0\" y=\"52.4\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"98.4\" y=\"52.4\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"109.8\" y=\"52.4\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"121.2\" y=\"52.4\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"132.6\" y=\"52.4\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"144.0\" y=\"52.4\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.