 x=\"109.8\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"121.2\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"132.6\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"144.0\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"155.4\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"166.8\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"178.2\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"189.6\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"201.0\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"212.4\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"223.8\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"235.2\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"246.6\" y=\"100.0\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"30.0\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"41.4\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"52.8\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"64.2\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"75.6\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"#3b82f6\" stroke=\"none\" stroke-width=\"0.8\"/><rect x=\"87.0\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"98.4\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"109.8\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"121.2\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"132.6\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"144.0\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"155.4\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"166.8\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"178.2\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"189.6\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"201.0\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"212.4\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"223.8\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"235.2\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><rect x=\"246.6\" y=\"110.4\" width=\"10\" height=\"9\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"0.8\"/><text x=\"170\" y=\"130\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">一部だけ無作為に抜き取って検査する</text></svg>", "terms": [["全数検査", "対象となる製品を1つ残らず全部検査すること。全数調査にあたる"], ["抜取検査", "対象の一部を無作為に抜き取って検査すること。標本調査にあたる"]], "think": "なぜ同じ『検査』でも2つの呼び方があるのかがカギ。1000個全部を検査すれば不良品を見逃す心配はほぼ無くなるが、時間もコストもかかり、検査自体が製品を壊してしまう(たとえば強度検査で製品を壊れるまで引っぱる)場合は全数検査ができない。そこで、母集団の一部だけを無作為に抜き取って調べ、そこから母集団全体の品質を推測する抜取検査(標本調査)を使う。全数調査と標本調査のどちらを選ぶかというトレードオフ(時間・コスト・検査で壊れるかどうか)は、品質管理の検査方法を選ぶ場面でもそのまま当てはまる。", "vs": "『検査』という言葉だけを見ると同じに思えるが、全数検査と抜取検査では『対象を全部見るか、一部だけ見るか』という前提がまったく違う。抜取検査の結果は、あくまで抜き取った100個から1000個全体を推測した値であり、1000個全部を直接確認したわけではないことを忘れない。", "why_asked": "品質管理の検査方法を選ぶ場面で、全数調査・標本調査という統計の基本概念がそのまま使われている。既に学んだ知識が別の場面でも通用することを確認する、つながりの問題。", "usecase": "製品を壊さないと検査できない場合(強度試験など)や、大量生産で全数検査に時間がかかりすぎる場合に、抜取検査(標本調査)を使って品質を確認する。", "opt": ["正解。1000個全部を検査する全数検査は全数調査に、100個だけ抜き取る抜取検査は標本調査に、それぞれ対応する。", "全数検査と抜取検査の対応が入れ替わっている。全部を検査するのが全数調査にあたる全数検査、一部を抜き取るのが標本調査にあたる抜取検査。", "対象を1つ残らず全部調べる全数検査は、標本調査ではなく全数調査にあたる。すべてが標本調査に分類されるわけではない。", "対象の一部だけを無作為に抜き取る抜取検査は、全数調査ではなく標本調査にあたる。すべてが全数調査に分類されるわけではない。"]}'),

  ('stats19-q10', '品質管理',
   'ここまで学んできた管理図・工程能力指数などの品質管理の考え方は、実際にどのような場面で使われているか。最も適切なのはどれか？',
   NULL::text,
   '["生産ラインの部品寸法やコールセンターの応答時間、データのばらつきを継続的に監視する場面", "一度きりのイベントの来場者数を、開催が終わったあとに1回だけ集計して記録するだけの場面", "過去のデータやばらつきの記録をまったく使わず、担当者の勘だけで良品・不良品を判断する場面", "手作業だけで行う昔ながらの工程には使えず、機械化された生産ラインだけに限られている考え方"]',
   0, '[0]', 'single',
   '{"asked": "品質管理の考え方(管理図・工程能力指数など)が、実際にはどんな場面で使われているか。", "point": "品質管理は、製造業の生産ラインに限らず、日々くり返し発生するデータのばらつきを継続的に監視する場面ならどこでも使われる。", "kid": "品質管理の道具は、工場の部品づくりだけのものではない。『毎日・毎時間くり返し発生するデータに、いつもと違うブレが出ていないか』を見張りたい場面なら、業種を問わず使われている。", "eg": "コールセンターでいうと、毎日のお客様対応にかかる時間を管理図のようにプロットしておけば、『今日はいつもよりかなり待たせている』という変化にすぐ気づける。工場のねじの寸法を見張るのと同じ発想を、応答時間という別のデータに当てはめている。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">業種を問わず、くり返しデータのばらつきを見張る</text><text x=\"90\" y=\"28\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">生産ライン</text><rect x=\"65\" y=\"42\" width=\"50\" height=\"14\" fill=\"#2a2f3f\"/><rect x=\"72\" y=\"34\" width=\"8\" height=\"10\" fill=\"#2a2f3f\"/><rect x=\"88\" y=\"30\" width=\"8\" height=\"14\" fill=\"#2a2f3f\"/><text x=\"90\" y=\"68\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">部品の寸法</text><line x1=\"45\" y1=\"80\" x2=\"135\" y2=\"80\" stroke=\"#60a5fa\" stroke-dasharray=\"2 2\" stroke-width=\"0.8\"/><polyline points=\"50,96 70,88 90,100 110,86 130,94\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.6\"/><line x1=\"45\" y1=\"106\" x2=\"135\" y2=\"106\" stroke=\"#60a5fa\" stroke-dasharray=\"2 2\" stroke-width=\"0.8\"/><text x=\"250\" y=\"28\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">コールセンター</text><circle cx=\"250\" cy=\"45\" r=\"11\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"2\"/><line x1=\"250\" y1=\"45\" x2=\"250\" y2=\"37\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"250\" y1=\"45\" x2=\"256\" y2=\"48\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><text x=\"250\" y=\"68\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">応答時間</text><line x1=\"205\" y1=\"80\" x2=\"295\" y2=\"80\" stroke=\"#60a5fa\" stroke-dasharray=\"2 2\" stroke-width=\"0.8\"/><polyline points=\"210,94 230,100 250,88 270,98 290,92\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.6\"/><line x1=\"205\" y1=\"106\" x2=\"295\" y2=\"106\" stroke=\"#60a5fa\" stroke-dasharray=\"2 2\" stroke-width=\"0.8\"/><text x=\"170\" y=\"126\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">扱うデータは違っても、見張り方の発想は同じ</text></svg>", "terms": [["継続的な監視", "一度きりではなく、日々くり返しデータをとって見張り続けること。品質管理の道具が力を発揮する場面"]], "think": "なぜ品質管理が製造業以外にも広がるのかがカギ。管理図や工程能力指数がしていることは、『くり返し発生するデータのばらつきを、時間の流れの中で見張り、いつもと違う変化に早く気づく』という、データの種類を問わない汎用的な仕組み。部品の寸法もコールセンターの応答時間も、どちらも『日々くり返し発生し、ばらつきがあり、いつもと違う変化に早く気づきたい』という条件を満たしているので、同じ道具がそのまま使える。一度きりのイベントの集計のように、くり返し発生しないデータには、この『いつもと比べる』という発想自体が当てはまらない。", "vs": "『品質管理=工場の話』という思い込みは、道具の生まれた場所(製造業)と、道具が使える範囲を混同している。管理図のしくみそのものは、くり返し発生するデータであれば業種を問わず使える。", "why_asked": "品質管理の一連の考え方(ばらつきの管理・管理図・偶然原因と異常原因・工程能力指数)を学んだ最後に、これらが実際にどう役立つ知識なのかを結びつけておくことで、単元全体の意味が腹落ちする。", "usecase": "製造業の生産ラインの寸法・重さの監視、コールセンターの応答時間や対応件数の監視、Webサービスのエラー発生率の監視など、日々くり返し発生するデータを見張るあらゆる場面。", "opt": ["正解。製造業の生産ラインの監視だけでなく、コールセンターの応答時間の管理など、日々くり返し発生するデータのばらつきを継続的に見張る場面全般で使われる。", "一度きりのイベントの集計のように、くり返し発生しないデータには、『いつもと比べて異常はないか』を見張る品質管理の発想自体が当てはまりにくい。", "品質管理はむしろ、過去のデータやばらつきの記録をもとに、勘に頼らず判断しようとする考え方。データを一切使わない判断とは正反対の発想。", "品質管理の考え方は業種や機械化の有無を問わず、くり返し発生するデータのばらつきを見張りたい場面であれば、手作業の工程にも使える。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
